import { IoTicket } from "react-icons/io5";

interface cardProps {
    title: string;
    text: string;
    text2?: string;
    action?: () => void;
    btnText?: string
}

export default function EventCard({title, text, text2, action, btnText}: cardProps) {
    return (
        <div style={{width: '100%', backgroundColor: '#D72229'}}>
            <IoTicket />

            <div>
                <p>{title}</p>
                <p>{text}</p>
            </div>
            
            {
                text2 && (
                    <p>{text2}</p>
                )
            }
            {
                action && (
                    <button onClick={action}>{btnText}</button>
                )
            }
            
        </div>
    )
}